// Loads the API spec, contract and fixtures of this Actor directory for the three version tests.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { norm } from '../src/lib/index.js';

export const actorDir = fileURLToPath(new URL('..', import.meta.url));
const readJson = (p) => JSON.parse(readFileSync(p, 'utf8'));

export const api = readJson(join(actorDir, 'api.json'));
export const contractPath = join(actorDir, 'contract.json');
export const contract = existsSync(contractPath) ? readJson(contractPath) : null;

// fixtures/<name>/{meta.json, page.txt, page.html?, expected.json}
export const loadFixtures = () => {
  const dir = join(actorDir, 'fixtures');
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => {
    const f = join(dir, d.name);
    return {
      name: d.name,
      meta: readJson(join(f, 'meta.json')),
      text: readFileSync(join(f, 'page.txt'), 'utf8'),
      html: existsSync(join(f, 'page.html')) ? readFileSync(join(f, 'page.html'), 'utf8') : '',
      expected: readJson(join(f, 'expected.json')),
    };
  });
};

export const key = (v) => `${v.metric}\u0000${norm(v.value)}`;

// Every expected value must appear among the produced ones (as a multiset on metric + value).
export const missingExpected = (expected, produced) => {
  const have = new Map();
  for (const p of produced) have.set(key(p), (have.get(key(p)) ?? 0) + 1);
  const missing = [];
  for (const e of expected) {
    const n = have.get(key(e)) ?? 0;
    if (n > 0) have.set(key(e), n - 1);
    else missing.push(e);
  }
  return missing;
};

export const rowCount = (values) => new Set(values.map((v) => v.row)).size;

// Contract test: versions are additive only. This version's output schema keeps every field of
// the version it replaces (contract.json), and extract() emits no field outside the schema.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { extract } from '../src/extract.js';
import { api, contract, loadFixtures } from './harness.js';

const schemaFields = Object.keys(api.outputSchema?.properties ?? {});

test('output schema is a superset of the previous version', { skip: contract ? false : 'no contract.json' }, () => {
  const dropped = contract.fields.filter((f) => !schemaFields.includes(f));
  assert.deepEqual(dropped, [], `fields removed from the output schema: ${dropped.join(', ')}`);
  for (const f of contract.fields) {
    const prev = contract.outputSchema?.properties?.[f]?.type;
    const cur = api.outputSchema.properties[f]?.type;
    if (prev) assert.equal(cur, prev, `field ${f} changed type from ${prev} to ${cur}`);
  }
});

test('extract emits only schema fields', { skip: loadFixtures().length ? false : 'no fixtures/' }, async () => {
  for (const fx of loadFixtures()) {
    const out = await extract({ url: fx.meta.url, text: fx.text, html: fx.html });
    const extra = [...new Set(out.map((v) => v.metric))].filter((m) => !schemaFields.includes(m));
    assert.deepEqual(extra, [], `fields outside the schema: ${extra.join(', ')}`);
  }
});

// Fixtures test: on each saved Tier 0 page, extract() reproduces every audited value, and every
// value it produces passes the quote anchor against that saved page.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { extract } from '../src/extract.js';
import { processPage, fieldsOf } from '../src/run.js';
import { api, loadFixtures, missingExpected } from './harness.js';

const fixtures = loadFixtures();
const fields = fieldsOf(api);

if (!fixtures.length) test('fixtures', { skip: 'no fixtures/ (run scripts/make-fixtures.mjs <api>)' }, () => {});

for (const fx of fixtures) {
  test(`fixture ${fx.name}: reproduces the audited values, all anchored`, async () => {
    const page = { text: fx.text, html: fx.html, method: 'fixture', country: null };
    const r = await processPage({ url: fx.meta.url, page, extract, fields, observedAt: fx.meta.observedAt ?? new Date(0).toISOString() });
    assert.equal(r.error, null, r.error ?? '');

    const unanchored = r.items.filter((i) => i.status !== 'extracted');
    assert.equal(unanchored.length, 0,
      `${unanchored.length}/${r.items.length} produced values fail the quote anchor, e.g.\n${JSON.stringify(unanchored.slice(0, 5), ['row', 'metric', 'value', 'excerpt'], 1)}`);

    const missing = missingExpected(fx.expected, r.items);
    assert.equal(missing.length, 0,
      `${missing.length}/${fx.expected.length} audited values were not produced, e.g.\n${JSON.stringify(missing.slice(0, 8), null, 1)}`);
  });
}

